// Display helpers: amounts in a coin's display units, short identifiers, times.
import { hex } from './bytes';

export function formatAmount(amount: bigint, decimals: number, maxFraction = decimals): string {
  if (decimals === 0) return group(amount.toString());
  const scale = 10n ** BigInt(decimals);
  const whole = amount / scale;
  let fraction = (amount % scale).toString().padStart(decimals, '0');
  fraction = fraction.slice(0, maxFraction).replace(/0+$/, '');
  return fraction ? `${group(whole.toString())}.${fraction}` : group(whole.toString());
}

function group(digits: string): string {
  return digits.replace(/\B(?=(\d{3})+(?!\d))/g, ' ');
}

/**
 * Parses `12.5` (or `12,5`) into base units; throws on bad input. Groups may be
 * spaced (`1 000`), but a comma before exactly three digits is refused: `1,000`
 * reads as one to some people and a thousand to others.
 */
export function parseAmount(text: string, decimals: number): bigint {
  const spaced = text.trim().replace(/[\s_]/g, '');
  if (/^[1-9]\d*,\d{3}$/.test(spaced)) throw new Error('write a thousand as 1000 and decimals with a dot, like 1.5');
  const t = spaced.replace(/^(\d+),(\d*)$/, '$1.$2');
  const m = /^(\d+)(?:\.(\d*))?$/.exec(t);
  if (!m) throw new Error('enter an amount like 12.5');
  const fraction = m[2] ?? '';
  if (fraction.length > decimals) throw new Error(`at most ${decimals} decimal places`);
  const scale = 10n ** BigInt(decimals);
  return BigInt(m[1]) * scale + (fraction ? BigInt(fraction.padEnd(decimals, '0')) : 0n);
}

export function shortId(bytes: Uint8Array | string, head = 6, tail = 4): string {
  const h = typeof bytes === 'string' ? bytes : hex(bytes);
  return h.length <= head + tail ? h : `${h.slice(0, head)}…${h.slice(-tail)}`;
}

export function nowSeconds(): number {
  return Math.floor(Date.now() / 1000);
}

export function formatDuration(seconds: number): string {
  if (seconds < 60) return `${seconds} s`;
  if (seconds < 3600) return `${Math.round(seconds / 60)} min`;
  if (seconds < 86_400) return `${(seconds / 3600).toFixed(seconds % 3600 ? 1 : 0)} h`;
  return `${(seconds / 86_400).toFixed(seconds % 86_400 ? 1 : 0)} d`;
}

/** `in 2.5 d`, `3 min ago` or `now`. */
export function relativeTime(at: number | bigint): string {
  const t = Number(at);
  const delta = t - nowSeconds();
  if (Math.abs(delta) < 5) return 'now';
  return delta > 0 ? `in ${formatDuration(delta)}` : `${formatDuration(-delta)} ago`;
}

export function formatTime(at: number | bigint): string {
  const d = new Date(Number(at) * 1000);
  return d.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' });
}

/** The clock time of `at` (seconds), like `09:24`. */
export function formatClock(at: number): string {
  return new Date(at * 1000).toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
}

/** The day of `at` (seconds) as a list heading: `Today`, `Yesterday`, `Mon 13 Oct`, or with the year when it is another. */
export function dayLabel(at: number, now = nowSeconds()): string {
  const d = new Date(at * 1000);
  const today = new Date(now * 1000);
  const start = (x: Date) => new Date(x.getFullYear(), x.getMonth(), x.getDate()).getTime();
  const days = Math.round((start(today) - start(d)) / 86_400_000);
  if (days === 0) return 'Today';
  if (days === 1) return 'Yesterday';
  return d.toLocaleDateString(undefined, { weekday: 'short', day: 'numeric', month: 'short', year: d.getFullYear() === today.getFullYear() ? undefined : 'numeric' });
}

/** When something happened, short: the clock today, else the day and clock, or the day and year when it is another year. */
export function formatWhen(at: number, now = nowSeconds()): string {
  const d = new Date(at * 1000);
  if (dayLabel(at, now) === 'Today') return formatClock(at);
  const sameYear = d.getFullYear() === new Date(now * 1000).getFullYear();
  const day = d.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: sameYear ? undefined : 'numeric' });
  return sameYear ? `${day} ${formatClock(at)}` : day;
}

